    <b>Ведучий:</b> «Друзі, я щойно з "Сільпо" (або "АТБ"). У мене була дивна пригода на касі. Я побачив двох людей. Обидва витратили рівно по 200 гривень. До копійки! Але коли вони вийшли з магазину, я заглянув у їхні чеки... і зрозумів щось неймовірне про наше життя. Давайте проведемо розслідування!»</p>
    <h3>🧐 Крок 1: Огляд "Чеку №1" (Швидке задоволення)</h3>
    <p><i>(Дістає з першого пакета чипси, газовану воду, солодку вату)</i></br>
