    <p><b>Питання до дітей:</b> Як ви будете почуватися через годину після такої вечері? Чи захочеться вам їсти знову? Чи додасть це вам сили, щоб пробігти крос або вивчити вірш?»</br>
    <i>(Відповідь: Живіт буде повний, але сили не буде. Це їжа-пустушка).</i></p>
    <h3>🧐 Крок 2: Огляд "Чеку №2" (Інвестиція)</h3>
    <p><i>(Дістає з другого пакета картоплю, м'ясо, кукурудзу, помідори)</i></br>
    <b>Ведучий:</b> «А ось другий чек. Теж 200 гривень. Але подивіться, що є тут! Тут … перераховує складові пакету..</p>
