    3. «Як ви думаєте, чому більшість людей у магазині життя вибирають "чипси" (лінь), а не "картоплю" (корисні справи)?» (Бо це швидше і не треба працювати).</p>
    ''',
    '''
    <p>«Чи знаєте ви, що Ісус — це найкращий "Кухар" у світі? Він хоче допомогти нам приготувати з нашого часу щось неймовірно смачне, але Він чекає, поки ми принесемо Йому правильні "продукти"». Ми витрачаємо свій час на "чипси": лінь, пусті суперечки, безкінечні ігри в телефоні. Це приємно "хрумтить" зараз, але ввечері ми почуваємося порожніми. Ми просто "проїли" свій день.</p>
    <p><b>Ведучий:</b> «Друзі, наше життя — це теж супермаркет. Бог щоранку видає нам "чек" на 24 години. А чи знаєте ви, що час дорожчий за гроші? Бо гроші можна заробити знову, а вчорашній день — ніколи. І кожного дня ми ходимо по магазину справ і можливостей і в залежності що купляємо, так і живемо. Зараз покажу.</p>
    <h3>Гра-досвід: "10 секунд рішення — Куплю або подумаю ще"</h3>
