    <p><b>Механіка:</b> Діти стають на лінію. Стрибок вперед = «Куплю зараз». Крок назад = «Подумаю ще».</p>
    <p><b>Ситуації:</b></p>
    <ul>
      <li>Мама просить допомогти винести сміття, а у тебе якраз почався рівень у грі. (Якщо обираю іти допомагати, стрибок вперед, якщо трохи відкладаю - назад)</li>
      <li>Ти бачиш, що друг впав і розбив коліно. (Допоможу зразу - куплю, чи продовжу займатись своїми ділами - подумаю)</li>
      <li>Треба зібрати рюкзак на завтра, але так хочеться ще подивитися YouTube. (Куплю - зберу, подумаю - подивлюся YouTube)</li>
