    (До того, хто стрибнув вперед): «Тобі важко було прийняти це рішення так швидко?»</p>
    <p><b>Висновок:</b> Ті, хто стрибає вперед, - не завжди легко, але це крок до успіху. Казати «потім», - шлях швидкого задоволення, але шлях назад. І це вибір! Зроби його правильним.</p>
    <p>Про правильне і неправильне інвестування часу, трохи від нашого блогера. (Для більш дорослих - розбираємо Слайди, які додані на початку уроку)</p>
    <h3>Театр: "EDEN-TV: Битва Інвесторів" - Біблійна концепція</h3>
