    <b>Блогер:</b> «Ого, тут справжній вулик! Привіт, друже! Тобі Господар дав 5 Золотих Талантів-Годин. Це ж купа часу! Ти, мабуть, увесь день у мультики дивився?»</br>
    <b>Працівник №1:</b> <i>(витирає піт із чола)</i> «Які мультики? Я зрозумів головний секрет: Час — це насіння! Якщо його просто тримати в кулаці, воно засохне. Я вклав свої 5 годин у навчання: вивчив нову пісню для прослави, допоміг мамі на кухні та навчився лагодити іграшки. І дивіться — мої 5 монет перетворилися на 10! Мій час примножився, бо я став сильнішим і розумнішим! Мій час виріс, бо я не тримав його під подушкою!»</br>
