    <b>Працівник №2:</b> «Я вклав їх у Любов! Я побачив, що мій сусід сумує, і витратив свій час, щоб вислухати його. Потім я вчив малюків грати у футбол. Знаєте, коли ти віддаєш час іншим, твоє серце стає у два рази більшим! Тепер у мене 4 монети радості. Хто інвестує в друзів — ніколи не програє!»</p>
    <p><b>🎙️ Частина 3: Професійний копач ям (Лінивий раб) 🕳️</b></br>
