    <b>Блогер:</b> «А ось і наш лінивчик. Друже, у тебе була ціла золота монета — це 24 години твого життя щодня! Де вони? Ти теж збудував щось класне?»</br>
    <b>Лінивий Раб</b> <i>(важливо)</i>: ти нічого не розумієш. Я дуже обережний! Я подумав: "Навіщо мені щось робити зараз, якщо можна зробити... ніколи?". Я знав, що Бог серйозний. А раптом я б почав вчитися і в мене б не вийшло? А раптом я б допоміг комусь, а мені не подякували б? Страх і Лінь — мої найкращі друзі».</br>
    <b>Блогер:</b> «То де ж твій талант-час?»</br>
    <b>Лінивий Раб:</b> «Я поклав його у цю Стару Брудну Шкарпетку Ліні і закопав глибоко в землю! Я цілий день копав яму, щоб... нічого не робити. Я дуже втомився, поки ховав свій час від усіх. Ось, тримайте свою монету назад. Вона така ж сама, як була — холодна і нежива».</p>
    ''',
    '''
    <p><b>Блогер:</b> «Друзі, ви бачили це? Лінивий раб витратив стільки ж сил на те, щоб закопати свій час, скільки інші витратили на те, щоб його примножити.</br>
