    Бог дав нам таланти (наш час, сили, вміння) не для того, щоб ми їх "зберігали під подушкою". Він хоче, щоб ми ризикували, любили і діяли ЗАРАЗ!»</br>
    <b>Блогер до залу:</b> «То що, друзі? Будемо копати ями чи будемо сіяти насіння? Вибір за вами! З вами був EDEN-TV, не втрачайте свої золоті хвилини!»</p>
    <p><b>Опитування після театру:</b></p>
