    <p>З тактикою ворога ми розібралися, але не зупиняємося на цьому. Давайте зараз я розкажу про тактику БОНД, або як дійсно якісно проводити час.</p>
    <h3>Секретний код якісного часу «Б.О.Н.Д.»</h3>
    <ul>
      <li><b>Б — Бог.</b> Бог - Джерело.</li>
      <li><b>О — Опора (Друзі).</b> Тримай «живу сітку», не відпускай рук.</li>
      <li><b>Н — Наповнення (Радість).</b> Колекціонуй «стоп-кадри» щастя.</li>
      <li><b>Д — Дія (Вклад).</b> Будуй спільну вежу, віддаючи свій «пазл».</li>
    </ul>
    <p><b>Б — Бог.</b> Суть: Бог — це не просто "іконка" на екрані, це саме джерело живлення. Без Нього твій БОНД просто розрядиться.</br>
    <b>Інтерактивна ідея: «Режим польоту»</b></br>
    <b>Дія:</b> Попросіть усіх дітей увімкнути на своїх уявних смартфонах (руками) «режим польоту».</br>
    <b>Слова:</b> «Коли ти в режимі польоту — ти відключений від мережі. Ти ніби є, але сигналу немає. Спілкування з Богом — це вимкнути шум світу (режим польоту для Тік-Току), щоб почути Його голос. Бог говорить не в коментарях, а прямо в серце».</br>
    <b>Експеримент «Луна»:</b> Ведучий каже пошепки: «Я тебе люблю». Діти в першому ряду мають передати це далі по ланцюжку.</br>
    <b>Розбір:</b> «Щоб почути Бога, треба тиша. Якщо ти в навушниках 24/7 — ти пропустиш найважливіший дзвінок у житті».</p>
    ''',
    '''
    <p><b>О — Опора (Друзі).</b> Суть: Пам’ятаєте сітку на банці? Молекули води трималися разом. Так само і друзі.</br>
    <b>Гра: «Жива Сітка»</b></br>
    Діти стають у коло і беруться за руки (сплітають пальці, як сітка). Ведучий намагається «прорватися» всередину або виштовхнути когось із кола (не грубо, а як символ «зовнішніх обставин»).</br>
    <b>Ускладнення:</b> Коли хтось один відпускає руку (ображається) — сітка рветься, і «час» витікає.</br>
    <b>Розбір:</b> Чи легше було втриматися разом, ніж поодинці? Аналіз: Коли ми проводимо час з друзями без телефонів, ми створюємо ту саму «сітку», яка не дає нам впасти у депресію чи нудьгу.</p>
    <p><b>Н — Наповнення (Радість).</b> Суть: Це те, що залишається в «банку пам’яті», коли таймер зупиниться.</br>
    <b>Гра: «Стоп-Кадр»</b></br>
    Команда має за 10 секунд створити «живу картину» на тему щастя в таборі (наприклад: «Перемога у грі», «Вечірнє вогнище», «Смачний обід»). Ведучий робить уявний (або справжній) знімок: «Чіііз!». Потім діти мають закрити очі і згадати кожну деталь цієї картини.</br>
    <b>Розбір:</b> Чому ми пам'ятаємо свята, але не пам'ятаємо, як 3 години гортали стрічку в соцмережах? Аналіз: Бо мозок не записує порожнечу. Він записує емоції. Радісні моменти — це «цемент», який заклеює дірки ліні.</p>
    <p><b>Д — Дія (Вклад).</b> Суть: Коли ми віддаємо час іншим, він не зникає, а подвоюється.</br>
    <b>Гра: «Естафета Ресурсів»</b></br>
