    <b>Розбір:</b> Що цінніше: один пазл у кишені чи ціла картина на столі? Аналіз: «Вклад у когось» — це коли ти допомагаєш другу застелити ліжко або вислуховуєш його. Твій час перетворюється на чиюсь радість. А радість — це валюта, яка не знецінюється.</p>
    ''',
    '''
