    <p><b>Як вкрасти Дружбу (Любов):</b></br>
    <b>Метод "Вірус Обиди":</b> Закинути маленький файл з помилкою "Він тебе не поважає". Файл почне копіювати себе, поки не заблокує всі теплі почуття до людини.</p>
