    <p><b>ГЕРОЙ:</b> <i>(Пробує зробити крок)</i> Мені важко дихати... Це ж просто нитки! Я можу їх розірвати!</br>
    <b>БЛОГЕР:</b> <i>(Зупиняє його пальцем, звертаючись до зали)</i> Агенти, підкажіть йому в коментарях — чи можна розірвати тисячу ниток одночасно? Це ж класична DDoS-атака на волю! Його процесор перегрівся. Він хотів бути вільним, а став «мумією контенту».</p>
    <p><i>(Блогер підносить телефон впритул до обличчя Героя)</i></br>
