      <li>🗝️ <b>Істина дня: Ілюзія Безліміту.</b> Спочатку Бог створив людей (Адама і Єву) для вічного життя у спілкуванні з Ним — час був невичерпним подарунком (Non-stop). Але через їхній непослух (гріх) у світ увійшла смерть, і наш час на землі став обмеженим. Ми часто живемо в ілюзії, думаючи, що маємо "безліміт", поки не усвідомлюємо, що кожна хвилина витікає безповоротно і ліміт встановлений не нами. Ключовий вірш: 2 Петра 3:8: «Але не забувайте одного, любі мої, що для Господа один день — як тисяча років, а тисяча років — як один день».</li>
      <li>🌅 <b>Ранок:</b> Ранок починається зі звичайного табірного драйву, але раптово Координатор знаходить дивний кейс. Після його відкриття на великому екрані запускається загадковий цифровий відлік (Таймер). Ніхто не знає, що це. Координатор наївно припускає, що це гра, "лайки" або бали, які можна поповнити своєю активністю. Діти разом з ним бігають, грають в ігри, намагаючись "заробити" більше цифр. Вони разом з детективом намагаються зрозуміти природу цих цифр. ⏱️🏃‍♂️</li>
      <li>🌃 <b>Увечері:</b> Увечері першого дня напруга зростає. Приходить Детектив і приголомшує всіх: це не гра. Стався злочин. Хтось невидимий краде наш найцінніший ресурс — Час. Діти офіційно стають Агентами і підключаються до розслідування. Детектив за допомогою хімічного досліду доводить, що крадіжка реальна, хоч її і не видно неозброєним оком. Таймер продовжує свій невблаганний рух вниз. Зал розуміє: час витікає, і з цим треба щось робити. 🧪📉</li>
    </ul>

    <p><b>2️⃣ ДЕНЬ 2: Тягар Часу та Системна Помилка ⚠️</b></p>
    <ul>
      <li>🗝️ <b>Істина дня: Збій системи (Гріх).</b> Час стає важким "тягарем" не просто так — це наслідок тієї самої "системної помилки" (гріха), яку запустили перші люди і яку ми продовжуємо своїми неправильними рішеннями. Гріх ламає задуманий Богом порядок, робить життя хаотичним і краде нашу радість та можливості. Ключовий вірш: "Бо заплата за гріх — смерть, а дар Божий — вічне життя в Христі Ісусі, Господі нашім." (Римлян 6:23)</li>
      <li>🌅 <b>Ранок:</b> Ранок другого дня приносить нову проблему. Координатор з'являється на сцені, тягнучи за собою величезний, важкий мішок. Час став "важким". Система видає "Error". Координатор думає, що час тисне на нас, бо ми надто повільні, і намагається разом із дітьми "обігнати" його через швидкісні ігри. Але швидкість не знімає тягаря. Виявляється, що час стає важким через наші неправильні очікування та хаос у діях. 🎒🏃‍♀️</li>
      <li>🌃 <b>Увечері:</b> Увечері Детектив збирає докази на своїй дошці розслідувань. Через ігри-змагання між лідерами діти бачать, що навіть дорослі часто не вміють керувати часом і роблять помилки. Детектив приходить до висновку, що "тягар" — це наслідок наших власних неправильних виборів. З'являється перша зачіпка щодо того, хто ж насправді цей Злодій. 📌🕵️‍♂️</li>
    </ul>
    ''',
    '''
    <p><b>3️⃣ ДЕНЬ 3: Внутрішні Крадії та Ціна Зусиль 💪</b></p>
    <ul>
      <li>🗝️ <b>Істина дня: Внутрішні крадії та нове серце.</b> Головні злодії (лінь, образа, байдужість) ховаються всередині нас. Своїми силами ми не можемо "залатати" ці дірки в характері, нам потрібне партнерство з Творцем (народження згори), щоб зберегти своє серце і наповнити час якісним сенсом. Ключовий вірш: Ефесян 5:16: «Використовуйте кожну можливість, бо часи тепер лихі».</li>
      <li>🌅 <b>Ранок:</b> На ранок третього дня фокус розслідування змінюється. Детектив і Координатор розуміють, що головні злодії ховаються не зовні, а всередині нас. Це Лінь, Неуважність та Слабкість. Діти проходять тести на витривалість та пам'ять. Координатор вчить табір не просто витрачати час, а "складати його в скарбничку", перетворюючи кожну гру на якісний момент розвитку та перемоги над собою. 🧠🏅</li>
      <li>🌃 <b>Увечері:</b> Увечері відбувається переломний момент. Детектив наочно (через ефектний дослід) показує, як працюють зусилля: якщо ти розслаблений як болото — ти тонеш, якщо докладаєш сили — ти можеш стояти твердо. Учасники роблять свій вибір, голосуючи "вагою" (намистинами), і визнають, що без їхніх особистих зусиль Таймер не зупинити. ⚖️⏳</li>
    </ul>

    <p><b>4️⃣ ДЕНЬ 4: Чорна Діра та режим без питань 🕳️</b></p>
