      <li>🌅 <b>Ранок:</b> Ранок четвертого дня починається з паніки. Таймер раптом починає летіти з шаленою швидкістю (х500)! Координатор у розпачі — він лише на секунду зазирнув у телефон, а пів дня вже зникло. Табір дізнається про "Чорні діри уваги" (гаджети, пусті розмови). Щоб вижити, Агенти тренують максимальну пильність. Вони розуміють: якщо ти не пильнуєш свій час, Система "виб'є" тебе з гри. 📱🚀</li>
      <li>🌃 <b>Увечері:</b> Увечері ситуація стає критичною. Система намагається роз'єднати дітей, роблячи їх "третіми зайвими". Детектив розкриває страшну таємницю: ім'я головного Злодія — "Завтра" (Синдром відкладеного життя). Злодій переконує нас, що ми завжди маємо ще один день, крадучи наше сьогодення. Щоб остаточно позбавити нас шансу на опір, Система вводить "Режим без запитань" — повну заборону ставити будь-які запитання. Ціль Системи: забрати у табору критичне мислення. Адже якщо ти не можеш ставити запитання (собі, людям, Богу), ти не зможеш аналізувати ситуацію і приймати правильні, зважені рішення. Зал завмирає в напруженій невизначеності перед фіналом. 🤫🚫</li>
    </ul>
    ''',
    '''
    <p><b>5️⃣ ДЕНЬ 5: Момент Істини та Перемога "СЬОГОДНІ" 🏆</b></p>
    <ul>
      <li>🗝️ <b>Істина дня: СЬОГОДНІ.</b> Ілюзія "Завтра" — це найбільший обман. Єдиний реальний час для змін, віри, любові та примирення з Богом — це зараз. Адміністратор (Ісус) вже заплатив ціну за наші помилки, і ми маємо прийняти цей подарунок сьогодні. Ключовий вірш: 2 Коринтян 6:2: «...Ось тепер — час сприятливий, ось тепер — день спасіння!»</li>
      <li>🌅 <b>Ранок:</b> Ранок п'ятого дня — це фінішна пряма. Таймер показує критично малий час. Координатор закликає табір не здаватися і діяти миттєво. Через серію активних ігор діти вчаться не відкладати можливості. Зрештою, у хаосі паперових літачків вони знаходять головний доказ — зашифрований код із Біблії (2 Кор. 6:2), який стверджує: "Ось ТЕПЕР час сприятливий". Діти усвідомлюють, що "Потім" не існує. ✈️✉️</li>
      <li>🌃 <b>Увечері:</b> Настає кульмінація. Таймер доходить до нуля. Детектив розкриває головний інсайт: таймер показував не скільки часу залишилося до "кінця", а вікно МОЖЛИВОСТІ для прийняття рішення. Цифри на екрані перетворюються на слово "СЬОГОДНІ". Координатор у розпачі тримає свій зіпсований помилками ватман (минуле) і розуміє, що не може його "замалювати" добрими справами чи коректором — бруд гріха не зникає. Тоді Детектив відкриває план "Reset" (Великий Обмін): Бог знав, що ми зіпсуємо свої файли. Його Син, Ісус, маючи ідеально чистий аркуш, добровільно забрав наш брудний на Себе. Ціна вже заплачена. Детектив забирає у Координатора зіпсований ватман і дає йому абсолютно новий, чистий аркуш із гучною печаткою "СПЛАЧЕНО". 🔄📜</li>
      <li>🎇 <b>Фінал:</b> Герої разом із залом роблять головний висновок: єдиний час, над яким ми маємо владу для прощення, любові, віри та змін — це СЬОГОДНІ. Злодій переможений, бо табір навчився цінувати кожну мить свого життя. 🎉✅</li>
    </ul>

