    І також відео представлення команд за посиланням: <a href="https://www.youtube.com/watch?v=GIsRNx-y9lg&list=PLXJIzqdCb1erFfpFMk8GV_zmtHRalk-bs">YouTube Плейлист</a></p>
    ''',
    '''
    <h3>Система мотивації</h3>
    <p>🗺️ <b>Мапа прогресу</b> — це інтерактивний елемент табору, за допомогою якого підтримується динаміка та інтерес протягом усіх табірних днів.</p>
    <p>❓ <b>Як вона працює?</b></p>
    <ul>
      <li>🏁 На початку табору кожна команда отримує мапу та грає з нею до кінця табору.</li>
      <li>⏳ Після проходження певних ігор, станцій, квестів, загальнотабірок тощо команди отримують певну кількість кольорового піску, який наприкінці дня висипають у візуальну банку (або колбу) зі шкалою.</li>
      <li>🎲 Залежно від того, скільки позначок шкали на банці (колбі) подолано, стільки квадратиків на мапі учасники проходять за день (як у грі-бродилці).</li>
      <li>💡 Ми рекомендуємо встановити умови так, щоб команди проходили максимум 4–5 поділок шкали.</li>
      <li>👣 Наступного дня команда продовжує з того квадратика, на якому зупинилася вчора.</li>
      <li>🎁 На окремих квадратиках є призи.</li>
      <li>⚖️ Коли команда доходить до того чи іншого призу, вона може обрати: забрати його чи рухатися далі.</li>
      <li>🔄 Якщо команда забирає приз, вона повертається на старт і починає спочатку; якщо ж рухається далі — прямує до суперпризу.</li>
      <li>⚙️ Це правило є опційним: ви можете його змінити або взагалі скасувати. Наприклад, у разі вибору призу команда може не повертатися на старт, а продовжувати рухатися далі.</li>
    </ul>

    <h3>Реклама післятабірних зустрічей</h3>
    <p>Важливо після табору одразу запланувати наступну зустріч, щоб зберегти відносини. Учасники вже здружились між собою, з вами як наставниками. Треба не втратити цей зв'язок. Тому в останній день табору ми постійно наголошуємо про нашу наступну зустріч. І одразу кажемо де, коли і на котру годину вона буде.</p>

    <p><i>💡 <b>Інструкція до таймера:</b> Інформація в розробці...</i></p>
